// No control event is generated by the main test process. This driver must
// first prove that CREATE_NEW_CONSOLE attached only itself to a fresh console,
// then prove that every attached process is its own descendant before Ctrl+C.
func TestIsolatedConsoleCtrlC(t *testing.T) {
	build := t.TempDir()
	bootstrap := filepath.Join(build, "cudia.exe")
	launcher := filepath.Join(build, "launcher.exe")
	engine := filepath.Join(build, "test-engine.exe")
	buildNative(t, "./cmd/bootstrap", bootstrap)
	buildNative(t, "./cmd/launcher", launcher)
	buildNative(t, "./internal/client/testdata/engine", engine)
	launcherBytes, err := os.ReadFile(launcher)
	if err != nil {
		t.Fatal(err)
	}
	engineBytes, err := os.ReadFile(engine)
	if err != nil {
		t.Fatal(err)
	}
	keys, priv := testKeys(t)
	server, u := testServer(t, keys)
	p := testPayload()
	archive, _ := packageBytes(t, p, "normal", map[string][]byte{"launcher.exe": launcherBytes, "runtime/engine.exe": engineBytes, "defaults/release.txt": []byte("console test")})
	server.set(t, p, archive, priv)
	if err := u.initialize(context.Background(), "normal", server.manifest, writeArchive(t, archive)); err != nil {
		t.Fatal(err)
	}
	installed := filepath.Join(u.root, "bin", "cudia.exe")
	copyFile(t, bootstrap, installed)
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 40*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, exe, "-test.run=^TestConsoleCtrlCDriver$", "-test.v")
	cmd.SysProcAttr = &syscall.SysProcAttr{CreationFlags: 0x10, HideWindow: true} // CREATE_NEW_CONSOLE
	cmd.Env = append(cleanEngineEnv("PATH="+filepath.Join(u.root, "bin")), "CUDIA_TEST_CONSOLE_DRIVER=1", "CUDIA_TEST_CONSOLE_ROOT="+u.root, "CUDIA_TEST_CONSOLE_PARENT="+strconv.Itoa(os.Getpid()))
	b, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("isolated Ctrl+C driver failed: %v\n%s", err, b)
	}
	if strings.Contains(string(b), "CUDIA_CONSOLE_SKIP=") {
		t.Skipf("isolated console unavailable; no control event sent: %s", b)
	}
	if !strings.Contains(string(b), "CUDIA_CONSOLE_OK childExit=23") {
		t.Fatalf("missing exact Ctrl+C result: %s", b)
	}
	t.Logf("%s", bytes.TrimSpace(b))
}

func TestConsoleCtrlCDriver(t *testing.T) {
	if os.Getenv("CUDIA_TEST_CONSOLE_DRIVER") != "1" {
		return
	}
	self := uint32(os.Getpid())
	parent, err := strconv.ParseUint(os.Getenv("CUDIA_TEST_CONSOLE_PARENT"), 10, 32)
	if err != nil {
		t.Fatal("driver parent identity unavailable")
	}
	initial, err := consolePIDs()
	if err != nil || len(initial) != 1 || initial[0] != self {
		t.Skipf("CUDIA_CONSOLE_SKIP=CREATE_NEW_CONSOLE isolation not established: pids=%v error=%v", initial, err)
	}
	// Register before child startup: the event intentionally reaches the driver
	// too, but it must remain alive to observe the complete wrapper chain.
	interrupts := make(chan os.Signal, 1)
	signal.Notify(interrupts, os.Interrupt)
	defer signal.Stop(interrupts)
	root := os.Getenv("CUDIA_TEST_CONSOLE_ROOT")
	ready := filepath.Join(root, "console-engine-ready")
	cmd := exec.Command(filepath.Join(root, "bin", "cudia.exe"), "--test-interrupt", ready)
	cmd.Dir = root
	cmd.Env = cleanEngineEnv("PATH=" + filepath.Join(root, "bin"))
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	finished := make(chan struct{})
	var childErr error
	go func() { childErr = cmd.Wait(); close(finished) }()
	defer func() {
		select {
		case <-finished:
			return
		default:
		}
		// Failure/skip cleanup uses process ancestry and only our test children.
		// It never emits a control event or terminates a foreign console process.
		terminateTestDescendants(self, uint32(parent))
		select {
		case <-finished:
		case <-time.After(15 * time.Second):
			t.Error("owned console test children did not finish cleanup")
		}
	}()
	waitFile(t, ready)
	engineBytes, err := os.ReadFile(ready)
	if err != nil {
		t.Fatal(err)
	}
	enginePID, err := strconv.ParseUint(string(engineBytes), 10, 32)
	if err != nil {
		t.Fatal("engine PID unavailable")
	}
	pids, err := consolePIDs()
	if err != nil {
		t.Skipf("CUDIA_CONSOLE_SKIP=cannot inspect fresh console: %v", err)
	}
	parents, err := processParents()
	if err != nil {
		t.Skipf("CUDIA_CONSOLE_SKIP=cannot prove console process ownership: %v", err)
	}
	seen := map[uint32]bool{}
	for _, pid := range pids {
		if pid == uint32(parent) || pid == 9764 || !ownedDescendant(pid, self, parents) {
			t.Skipf("CUDIA_CONSOLE_SKIP=foreign console process %d; no event sent", pid)
		}
		seen[pid] = true
	}
	if len(pids) != 4 || !seen[self] || !seen[uint32(cmd.Process.Pid)] || !seen[uint32(enginePID)] {
		t.Skipf("CUDIA_CONSOLE_SKIP=expected driver/bootstrap/launcher/engine, got %v", pids)
	}
	// This is the only GenerateConsoleCtrlEvent call in the module. Group zero
	// targets this already-proven isolated console, never the parent's console.
	generate := kernel32.NewProc("GenerateConsoleCtrlEvent")
	ok, _, callErr := generate.Call(0, 0) // CTRL_C_EVENT, all processes in our new console
	if ok == 0 {
		t.Fatalf("GenerateConsoleCtrlEvent in isolated console failed: %v", callErr)
	}
	select {
	case <-finished:
		var exit *exec.ExitError
		if !errors.As(childErr, &exit) || exit.ExitCode() != 23 {
			t.Fatalf("wrapper exit=%v stdout=%q stderr=%q", childErr, stdout.String(), stderr.String())
		}
	case <-time.After(15 * time.Second):
		t.Fatal("isolated Ctrl+C did not release wrapper chain")
	}
	var report struct {
		Interrupt bool `json:"interrupt"`
		Exit      int  `json:"exit"`
	}
	if err := json.Unmarshal(stdout.Bytes(), &report); err != nil || !report.Interrupt || report.Exit != 23 || stderr.Len() != 0 {
		t.Fatalf("engine interrupt report=%q stderr=%q error=%v", stdout.String(), stderr.String(), err)
	}
	select {
	case <-interrupts:
	case <-time.After(time.Second):
		t.Fatal("driver did not observe its own console event")
	}
	fmt.Printf("CUDIA_CONSOLE_OK childExit=23 isolatedPids=%v engine=%s\n", pids, strings.TrimSpace(stdout.String()))
}

func terminateTestDescendants(self, parent uint32) {
	parents, err := processParents()
	if err != nil {
		return
	}
	for pid := range parents {
		if pid == self || pid == parent || pid == 9764 || !ownedDescendant(pid, self, parents) {
			continue
		}
		h, err := syscall.OpenProcess(syscall.PROCESS_TERMINATE, false, pid)
		if err != nil {
			continue
		}
		_ = syscall.TerminateProcess(h, 26)
		_ = syscall.CloseHandle(h)
	}
}

func consolePIDs() ([]uint32, error) {
	list := kernel32.NewProc("GetConsoleProcessList")
	pids := make([]uint32, 32)
	n, _, err := list.Call(uintptr(unsafe.Pointer(&pids[0])), uintptr(len(pids)))
	if n == 0 {
		return nil, err
	}
	if n > uintptr(len(pids)) {
		return nil, errors.New("unexpectedly large console process list")
	}
	return pids[:int(n)], nil
}
func processParents() (map[uint32]uint32, error) {
	snapshot, err := syscall.CreateToolhelp32Snapshot(syscall.TH32CS_SNAPPROCESS, 0)
	if err != nil {
		return nil, err
	}
	defer syscall.CloseHandle(snapshot)
	entry := syscall.ProcessEntry32{Size: uint32(unsafe.Sizeof(syscall.ProcessEntry32{}))}
	if err := syscall.Process32First(snapshot, &entry); err != nil {
		return nil, err
	}
	parents := map[uint32]uint32{}
	for {
		parents[entry.ProcessID] = entry.ParentProcessID
		err = syscall.Process32Next(snapshot, &entry)
		if err == syscall.ERROR_NO_MORE_FILES {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	return parents, nil
}
func ownedDescendant(pid, root uint32, parents map[uint32]uint32) bool {
	for n := 0; n < 64 && pid != 0; n++ {
		if pid == root {
			return true
		}
		next, ok := parents[pid]
		if !ok || next == pid {
			return false
		}
		pid = next
	}
	return false
}
